#include <iostream>
#include <stdexcept>
#include <exception>

int estimar(int piezas) {
    if (piezas < 0 || piezas > 10) {
        throw std::invalid_argument{"Cantidad fuera de 0 a 10"};
    }
    if (piezas == 0) { return 0; }
    return 3 + 2 * piezas;
}

int main() {
    try {
        std::cout << estimar(12);
    } catch (const std::out_of_range& error) {
        std::cout << "Indice";
    } catch (const std::exception& error) {
        std::cout << "Otro fallo";
    }
    return 0;
}

