    std::vector<int> datos{2, 9};
    int indice{2};
    bool mostrarDiagnostico{false};
    try {
        int valor{datos.at(indice)};
        std::cout << valor;
    } catch (const std::out_of_range& error) {
        std::cout << "Indice invalido";
        if (mostrarDiagnostico) {
            std::cerr << error.what() << "\n";
